#include "tooling_model.hh"
namespace cellerator::compiler::tooling::v1 {std::vector<optimization_action> missed_optimization_actions(std::string_view s){std::vector<optimization_action> a;if(s.find("native")!=s.npos)a.push_back({"uncontracted-native-call","alias/effect uncertainty across field boundary","annotate effects(reads values)",0,true});if(s.find("unknown_profile")!=s.npos)a.push_back({"profile-widening","missing persistence facts","add persistent(structure)",0,true});if(s.find("canonical")!=s.npos)a.push_back({"canonicalization","order conversion prevents fusion","retain execution_order",240,true});return a;}}
